// Literal port of the team's Casa3DSDK (module furniture/taps). Generated by codemod and reviewed; see MIGRATION.md.
import type { Kernel, Shared } from '../kernel-types.js';

export function installFurnitureTaps(K: Kernel, shared: Shared): void {
  // ---------- plumbing ----------
  shared.tapCount = 0;
  // countertop tap (sink): base, column, arched spout, lever (handle part) and hidden water thread (tap_water part)
  function counterTap(K, x, y, z, reach, back, meta: any = {}) {
    const cr = 0xc4c8cc, id = 'tap_' + (K.M.seed || '') + '_' + (shared.tapCount++);
    K.c('metal', x, y, z, 0.028, 0.012, cr); K.c('metal', x, y + 0.012, z, 0.014, 0.12, cr);
    const pts = []; for (let i = 0; i <= 5; i++) { const a = Math.PI / 2 - i * (Math.PI * 0.62) / 5; pts.push([x, y + 0.13 + Math.sin(a) * 0.075, z + (1 - Math.cos(a)) * reach * 0.5 + (i > 0 ? 0 : 0)]); }
    for (let i = 0; i < 5; i++) K.t('metal', pts[i], pts[i + 1], 0.0115, cr);
    const tip = pts[5]; K.t('metal', tip, [tip[0], tip[1] - 0.045, tip[2]], 0.0135, cr); K.e('metal', tip[0], tip[1], tip[2], 0.0125, 0.025, cr);
    K.part('handle', x, y + 0.075, z, () => { K.t('metal', [x, y + 0.075, z], [x + 0.06, y + 0.095, z], 0.0075, cr); K.e('metal', x + 0.062, y + 0.096, z, 0.011, 0.022, cr); K.c('metal', x, y + 0.07, z, 0.017, 0.012, 0xa8acb0); },
      Object.assign({ id: id + '_m', target: id, room: K.M.room, opens: { type: 'swing', axis: [0, 1, 0], angle: -0.7 }, waterId: id + '_a' }, meta));
    const ya = tip[1] - 0.05;
    K.part('water_tap', tip[0], ya, tip[2], () => { K.t('water', [tip[0], ya, tip[2]], [tip[0], y - back, tip[2]], 0.006, 0xcfe8f4); }, { id: id + '_a', target: id, hidden: true, fluid: 'water' });
    return id;
  }
  // wall tap (laundry tub, garden): plate on the wall (z = zw), pipe, elbow and spout, cross handwheel
  function wallTap(K, x, y, zw, direction, back, meta: any = {}) {
    const cr = 0xc4c8cc, id = 'tap_' + (K.M.seed || '') + '_' + (shared.tapCount++), s = direction || 1;
    K.t('metal', [x, y, zw], [x, y, zw + s * 0.025], 0.03, cr); K.t('metal', [x, y, zw + s * 0.02], [x, y, zw + s * 0.1], 0.016, cr);
    K.e('metal', x, y, zw + s * 0.105, 0.019, 0.04, cr); K.t('metal', [x, y, zw + s * 0.105], [x, y - 0.065, zw + s * 0.105], 0.0125, cr); K.c('metal', x, y - 0.075, zw + s * 0.105, 0.0145, 0.014, 0xa8acb0);
    K.t('metal', [x, y + 0.0, zw + s * 0.06], [x, y + 0.045, zw + s * 0.06], 0.009, cr);
    K.part('handle', x, y + 0.045, zw + s * 0.06, () => { K.c('metal', x, y + 0.045, zw + s * 0.06, 0.012, 0.012, cr); K.b('metal', x, y + 0.057, zw + s * 0.06, 0.085, 0.012, 0.014, cr); K.b('metal', x, y + 0.057, zw + s * 0.06, 0.014, 0.012, 0.085, cr); K.e('metal', x, y + 0.063, zw + s * 0.06, 0.012, 0.016, 0xa8acb0); },
      Object.assign({ id: id + '_m', target: id, room: K.M.room, opens: { type: 'swing', axis: [0, 1, 0], angle: 1.6 }, waterId: id + '_a' }, meta));
    const ya = y - 0.08;
    K.part('water_tap', x, ya, zw + s * 0.105, () => { K.t('water', [x, ya, zw + s * 0.105], [x, back, zw + s * 0.105], 0.0065, 0xcfe8f4); }, { id: id + '_a', target: id, hidden: true, fluid: 'water' });
    return id;
  }
  Object.assign(K, { counterTap, wallTap });
}
